const moment = require('moment');

const pickupDate = moment().add(5, 'days').format("YYYY-MM-DD");
const dueDateInvalid = moment().add(5 - 67, 'days').format("YYYY-MM-DD");

pm.variables.set("patch_pickup_date", pickupDate);
pm.variables.set("patch_due_date_invalid", dueDateInvalid);

const moment = require('moment');

// Fetch equipment list and pick a random one
const baseUrl = pm.environment.get("base_url") || pm.collectionVariables.get("base_url");
pm.sendRequest({ url: baseUrl + "/api/equipment", method: "GET" }, function (err, res) {
    if (!err && res.code === 200) {
        const equipments = res.json().results;
        if (Array.isArray(equipments) && equipments.length > 0) {
            const randomIndex = Math.floor(Math.random() * equipments.length);
            pm.variables.set("patch_random_equipment_id", equipments[randomIndex].id);
        } else {
            // Fallback to existing equipment_id if list is empty or unexpected shape
            pm.variables.set("patch_random_equipment_id", pm.collectionVariables.get("equipment_id"));
        }
    } else {
        pm.variables.set("patch_random_equipment_id", pm.collectionVariables.get("equipment_id"));
    }
});

// Shift due_date forward by 1 day from the current due_date (or today + 4 days as fallback)
const newDueDate = moment().add(4, 'days').format("YYYY-MM-DD");
pm.variables.set("patch_valid_due_date", newDueDate);

pm.test("status is 200", function () { pm.response.to.have.status(200); });

var jsonData = pm.response.json();
pm.test("due_date is updated", function () {
    pm.expect(jsonData.due_date).to.eql(pm.variables.get("patch_valid_due_date"));
});
pm.test("equipment_id is updated", function () {
    pm.expect(jsonData.equipment.id).to.eql(pm.variables.get("patch_random_equipment_id"));
});

pm.test("status is 201", function () { pm.response.to.have.status(201); });

var jsonData = pm.response.json();
