// Auto-attach the CSRF header captured from the last login/register
// response, on every request. Harmless on GETs (server ignores it there).
const token = pm.collectionVariables.get('csrf_token');
if (token) {
    pm.request.headers.upsert({ key: 'X-CSRFToken', value: token });
}

// After every response, refresh csrf_token from whatever csrftoken cookie
// is now in the jar (set fresh on every login/register response).
const csrfCookie = pm.cookies.get('csrftoken');
if (csrfCookie) {
    pm.collectionVariables.set('csrf_token', csrfCookie);
}
